-- Copy of each user's notebook, sent by the phone when an account exists.
-- Discretion rules: a night is located by department only, private by default,
-- and a shared night is visible to others only once it is over (from the next day).

CREATE TABLE public.nights (
  -- Generated by the phone, so a night created offline keeps its id once synced.
  id uuid PRIMARY KEY,
  owner uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles (id) ON DELETE CASCADE,
  date date NOT NULL,
  -- Null: the department hasn't been chosen yet.
  department text REFERENCES public.departments (code),
  title text NOT NULL DEFAULT '' CHECK (char_length(title) <= 80),
  comment text NOT NULL DEFAULT '' CHECK (char_length(comment) <= 2000),
  shared boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX nights_owner ON public.nights (owner, date DESC);

CREATE TABLE public.night_entries (
  id uuid PRIMARY KEY,
  night_id uuid NOT NULL REFERENCES public.nights (id) ON DELETE CASCADE,
  -- Exactly one of the two: a soundsystem or an artist was heard.
  soundsystem_id uuid REFERENCES public.soundsystems (id) ON DELETE CASCADE,
  artist_id uuid REFERENCES public.artists (id) ON DELETE CASCADE,
  -- Null: not rated.
  rating smallint CHECK (rating BETWEEN 1 AND 5),
  comment text NOT NULL DEFAULT '' CHECK (char_length(comment) <= 1000),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK ((soundsystem_id IS NULL) <> (artist_id IS NULL))
);

CREATE INDEX night_entries_night ON public.night_entries (night_id);
CREATE INDEX night_entries_soundsystem ON public.night_entries (soundsystem_id);
CREATE INDEX night_entries_artist ON public.night_entries (artist_id);

CREATE FUNCTION public._touch_night()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.owner := OLD.owner;
  NEW.created_at := OLD.created_at;
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE TRIGGER nights_touch BEFORE UPDATE ON public.nights
  FOR EACH ROW EXECUTE FUNCTION public._touch_night();

-- A night someone else may read: shared, over, and its owner not blocked by the reader.
CREATE FUNCTION public._night_is_public(p_night public.nights)
RETURNS boolean
LANGUAGE sql
STABLE
SET search_path = ''
AS $$
  SELECT p_night.shared
    AND p_night.date < current_date
    AND NOT EXISTS (
      SELECT 1 FROM public.blocks
      WHERE blocks.blocker = (select auth.uid()) AND blocks.blocked = p_night.owner
    );
$$;

ALTER TABLE public.nights ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.night_entries ENABLE ROW LEVEL SECURITY;

CREATE POLICY nights_select_own_or_public
  ON public.nights FOR SELECT
  TO authenticated
  USING ((select auth.uid()) = owner OR public._night_is_public(nights));

CREATE POLICY nights_insert_own
  ON public.nights FOR INSERT
  TO authenticated
  WITH CHECK ((select auth.uid()) = owner);

CREATE POLICY nights_update_own
  ON public.nights FOR UPDATE
  TO authenticated
  USING ((select auth.uid()) = owner)
  WITH CHECK ((select auth.uid()) = owner);

CREATE POLICY nights_delete_own
  ON public.nights FOR DELETE
  TO authenticated
  USING ((select auth.uid()) = owner);

CREATE POLICY night_entries_select_visible
  ON public.night_entries FOR SELECT
  TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.nights
    WHERE nights.id = night_entries.night_id
      AND ((select auth.uid()) = nights.owner OR public._night_is_public(nights))
  ));

CREATE POLICY night_entries_insert_own
  ON public.night_entries FOR INSERT
  TO authenticated
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.nights WHERE nights.id = night_entries.night_id AND nights.owner = (select auth.uid())
  ));

CREATE POLICY night_entries_update_own
  ON public.night_entries FOR UPDATE
  TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.nights WHERE nights.id = night_entries.night_id AND nights.owner = (select auth.uid())
  ))
  WITH CHECK (EXISTS (
    SELECT 1 FROM public.nights WHERE nights.id = night_entries.night_id AND nights.owner = (select auth.uid())
  ));

CREATE POLICY night_entries_delete_own
  ON public.night_entries FOR DELETE
  TO authenticated
  USING (EXISTS (
    SELECT 1 FROM public.nights WHERE nights.id = night_entries.night_id AND nights.owner = (select auth.uid())
  ));

REVOKE ALL ON FUNCTION public._night_is_public(public.nights) FROM public, anon;
GRANT EXECUTE ON FUNCTION public._night_is_public(public.nights) TO authenticated;
